-- S03: 32 лимита Банка ВТБ (7702070139) из реальных продуктов справочника stg_file_client_limit.
-- 12 продуктов x 3 «среза» (КБ активный / ИБ активный / ИБ не активен) = 36 → берём первые 32.
INSERT INTO sbox_rsk_drt.t_lm_1_3_limits
(inn, client_name, gk_crm_id, gk_name, owner, limit_id, currency, product, start_date, end_date,
 src_status, limit_status, rate, lim_value, lim_utiled, rest_lim, client_limits, lim_top, client_raroc)
SELECT
  '7702070139', 'Банк ВТБ (ПАО)', '1-X8TS15V', 'ГК ВТБ',
  CASE s.k WHEN 1 THEN 'Корпоративный блок' ELSE 'Инвестиционный блок' END,
  CASE s.k WHEN 1 THEN 'PRGNZ~4' || lpad(p.rn::text, 8, '0') ELSE (8000 + p.rn * 10 + s.k)::text END,
  p.currency,
  p.limit_product,
  DATE '2025-09-12',
  CASE s.k WHEN 3 THEN DATE '2026-03-11' ELSE DATE '2026-09-11' END,
  CASE s.k WHEN 1 THEN 'КД подписана' WHEN 2 THEN 'Not violated' ELSE 'Closed' END,
  CASE s.k WHEN 3 THEN 'Не активен – Срок действия лимита истёк' ELSE 'Активен – Лимит доступен к утилизации' END,
  CASE s.k WHEN 1 THEN 13.25 ELSE NULL END,
  p.client_limit,
  round(p.client_limit * CASE s.k WHEN 1 THEN 0.30 WHEN 2 THEN 0.05 ELSE 1.00 END, 2),
  p.client_limit - round(p.client_limit * CASE s.k WHEN 1 THEN 0.30 WHEN 2 THEN 0.05 ELSE 1.00 END, 2),
  '2025-09-12 ' || CASE s.k WHEN 1 THEN 'КБ ' ELSE 'ИК ' END || p.limit_product || ' ' || p.client_limit::text || ' ' || p.currency,
  'В пределах норматива Н6',
  4.75
FROM (
  SELECT row_number() OVER (ORDER BY limit_product) AS rn, limit_product, currency, client_limit
  FROM sbox_rsk_drt.stg_file_client_limit
  WHERE client_inn = '7702070139' AND group_crm_id = '1-X8TS15V'
) p
CROSS JOIN (VALUES (1), (2), (3)) AS s(k)
ORDER BY p.rn, s.k
LIMIT 32;

